// The portfolio has a static page per language: index.html (English) and el/index.html (Greek,
// generated by tools/build-greek.mjs). This script remembers the visitor's choice and
// translates the few captions that board.js writes while the page is open.
(() => {
  const greek = window.tsakGreek || {};
  const language = document.documentElement.lang === "el" ? "el" : "en";
  window.siteLanguage = { t: (text) => (language === "el" ? greek[text] || text : text) };

  const toggle = document.querySelector(".language-toggle");
  if (!toggle) return;
  toggle.addEventListener("click", () => {
    try {
      localStorage.setItem("tsakioan-language", language === "el" ? "en" : "el");
    } catch {}
    // Stay on the same section after switching.
    toggle.href = toggle.getAttribute("href").split("#")[0] + location.hash;
  });
})();
